// No renderer, no DOM — fully unit-testable in Node.

import * as THREE from 'three';

/** Upper bound for any generated height value. */
export const HEIGHT_MAX = 10;

/**
 * Deterministic PRNG (mulberry32).
 */
export function makeRng(seed) {
  let s = seed >>> 0;
  return function () {
    s = (s + 0x6d2b79f5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function hash2(ix, iz, seed) {
  let h = (ix * 374761393 + iz * 668265263 + seed * 2246822519) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

function smoothstep(t) {
  return t * t * (3 - 2 * t);
}

/** Seeded 2D value noise in [0, 1). */
function valueNoise(x, z, seed) {
  const ix = Math.floor(x);
  const iz = Math.floor(z);
  const fx = smoothstep(x - ix);
  const fz = smoothstep(z - iz);

  const n00 = hash2(ix, iz, seed);
  const n10 = hash2(ix + 1, iz, seed);
  const n01 = hash2(ix, iz + 1, seed);
  const n11 = hash2(ix + 1, iz + 1, seed);

  const nx0 = n00 + (n10 - n00) * fx;
  const nx1 = n01 + (n11 - n01) * fx;
  return nx0 + (nx1 - nx0) * fz;
}

/**
 * Ridged multifractal height in [0, HEIGHT_MAX].
 * Each octave contributes (1 - |2*noise - 1|)^2, sharpening crests.
 */
export function heightAt(x, z, seed) {
  const baseSeed = (seed >>> 0) || 1;
  let amplitude = 1;
  let frequency = 1 / 48; // base feature size in world units
  let sum = 0;
  let norm = 0;

  for (let octave = 0; octave < 5; octave++) {
    const n = valueNoise(x * frequency + 1000 * baseSeed, z * frequency + 2000 * baseSeed, baseSeed + octave * 7919);
    const ridge = 1 - Math.abs(2 * n - 1);
    sum += amplitude * ridge * ridge;
    norm += amplitude;
    amplitude *= 0.5;
    frequency *= 2.03; // slightly non-integer lacunarity avoids axis alignment
  }

  return (sum / norm) * HEIGHT_MAX;
}

/**
 * Build the terrain mesh.
 * @param {{seed?: number, size?: number, segments?: number}} [opts]
 * @returns {THREE.Mesh}
 */
export function createTerrain({ seed = 1337, size = 100, segments = 96 } = {}) {
  if (!Number.isFinite(seed)) throw new TypeError('seed must be a finite number');
  const geometry = new THREE.PlaneGeometry(size, size, segments, segments);
  geometry.rotateX(-Math.PI / 2); // lie flat on the XZ plane

  const position = geometry.attributes.position;
  for (let i = 0; i < position.count; i++) {
    position.setY(i, heightAt(position.getX(i), position.getZ(i), seed));
  }
  position.needsUpdate = true;
  geometry.computeVertexNormals();
  geometry.computeBoundingSphere();

  const material = new THREE.MeshStandardMaterial({
    color: 0x4f8a3d,
    flatShading: false,
  });

  return new THREE.Mesh(geometry, material);
}
