result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/scripts/screenshot.mjs", "content": "#!/usr/bin/env node
// Serves the project statically, loads public/index.html in headless
// chromium, captures console/page errors, waits for #status, and writes
// out/terrain.png. Exits nonzero on any console error or page error.

import http from 'node:http';
import { readFile } from 'node:fs/promises';
import { extname, join, normalize, resolve } from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';

process.env.PLAYWRIGHT_BROWSERS_PATH ||= '/ms-playwright';

const ROOT = resolve(fileURLToPath(new URL('..', import.meta.url)));
const HOST = '127.0.0.1';
const PORT = 0; // ephemeral

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript',
  '.mjs': 'text/javascript',
  '.css': 'text/css',
  '.json': 'application/json',
  '.png': 'image/png',
};

function startServer() {
  return new Promise((resolvePromise, reject) => {
    const server = http.createServer(async (req, res) => {
      try {
        const url = new URL(req.url, `http://${HOST}`);
        let pathname = decodeURIComponent(url.pathname);
        if (pathname === '/') pathname = '/public/index.html';
        // Serve from the project root (index.html uses /src/main.js and an
        // import map pointing at /node_modules/three/...).
        const filePath = join(ROOT, normalize(pathname));
        if (!resolve(filePath).startsWith(ROOT)) {
          res.writeHead(403).end('forbidden');
          return;
        }
        const body = await readFile(filePath);
        res.writeHead(200, { 'content-type': MIME[extname(filePath)] ?? 'application/octet-stream' });
        res.end(body);
      } catch {
        res.writeHead(404).end('not found');
      }
    });
    server.on('error', reject);
    server.listen(PORT, HOST, () => resolvePromise(server));
  });
}

async function main() {
  const server = await startServer();
  const { port } = server.address();
  const url = `http://${HOST}:${port}/`;

  const { chromium } = await import('playwright');
  const browser = await chromium.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-gpu', '--use-gl=swiftshader'],
  });

  const consoleErrors = [];
  const pageErrors = [];
  try {
    const page = await browser.newPage({ viewport: { width: 1024, height: 768 } });
    page.on('console', (msg) => {
      if (msg.type() === 'error') consoleErrors.push(msg.text());
    });
    page.on('pageerror', (err) => pageErrors.push(String(err)));

    await page.goto(url, { waitUntil: 'load', timeout: 30000 });
    const status = await page.waitForSelector('#status', { timeout: 15000 });
    const statusText = await status.textContent();

    await mkdirOut();
    await page.screenshot({ path: join(ROOT, 'out', 'terrain.png') });

    const title = await page.title();
    console.log(`title: ${title}`);
    console.log(`status: ${statusText}`);

    if (title !== 'terrain-ok') {
      consoleErrors.push(`unexpected title: ${title}`);
    }
  } finally {
    await browser.close();
    server.close();
  }

  for (const err of [...consoleErrors, ...pageErrors]) {
    console.error(`ERROR: ${err}`);
  }
  if (consoleErrors.length > 0 || pageErrors.length > 0) {
    process.exitCode = 1;
  } else {
    console.log('screenshot written to out/terrain.png');
  }
}

async function mkdirOut() {
  const { mkdir } = await import('node:fs/promises');
  await mkdir(join(ROOT, 'out'), { recursive: true });
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
"})
